import{_ as t}from"./chunks/console-rings.C4ZxRMHb.js";import{_ as o,o as r,c as s,a3 as a}from"./chunks/framework.DhF4LrUq.js";const u=JSON.parse('{"title":"Promote through rings","description":"Promote through rings - customize the ring ladder, run the promotion precheck, and widen a release ring by ring.","frontmatter":{"description":"Promote through rings - customize the ring ladder, run the promotion precheck, and widen a release ring by ring."},"headers":[],"relativePath":"how-to/console/rings-and-promotion.md","filePath":"how-to/console/rings-and-promotion.md"}'),n={name:"how-to/console/rings-and-promotion.md"};function i(l,e,h,p,d,g){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="promote-through-rings" tabindex="-1">Promote through rings <a class="header-anchor" href="#promote-through-rings" aria-label="Permalink to &quot;Promote through rings&quot;">​</a></h1><p>Rings are the progressive-delivery ladder: <code>engineering</code> → <code>qa</code> → <code>tenant-pilot</code> → <code>uat</code> → <code>production</code> by default. A release starts on one ring and promotion widens it one governed hop at a time — each hop re-checking the target ring&#39;s gates, approvals, eligibility, and policies. You shape the ladder on the <strong>Release rings</strong> screen and drive releases on the <a href="/shipperdog/snapshot/how-to/console/releases">release dashboard</a>.</p><p><img src="'+t+'" alt="The Release rings screen"></p><p>Why rings exist and how eligibility works is covered in <a href="/shipperdog/snapshot/concepts/rings-and-rollout">rings and rollout</a>.</p><h2 id="customize-the-ring-ladder" tabindex="-1">Customize the ring ladder <a class="header-anchor" href="#customize-the-ring-ladder" aria-label="Permalink to &quot;Customize the ring ladder&quot;">​</a></h2><ol><li><p>Open <strong>Release rings</strong>. The cards show your organization&#39;s effective vocabulary in progression order — <strong>Production stays last</strong>, enforced by the server.</p></li><li><p>The five system rings are read-only. To customize one, create your own ring under its code: click <strong>New ring</strong>, enter the system <strong>Code</strong> (lowercase kebab — a code matching a system entry builds your organization&#39;s shadow of it), a <strong>Name</strong>, and a <strong>Position</strong>.</p></li><li><p>Shape the ring in the same dialog:</p><ul><li><strong>Promotion policy</strong> — <em>Manual</em> (a person clicks) or <em>Automatic</em> (acts with the policy engine).</li><li><strong>Approval policy</strong> — the workflow name that binds approvals to hops into this ring; <strong>required for Production</strong>.</li><li><strong>Distribution channel</strong> — the channel reference its dispatches resolve (see <a href="/shipperdog/snapshot/how-to/console/distribution-channels">distribution channels</a>).</li><li><strong>Eligibility tenants</strong> and <strong>eligibility tester groups</strong> — narrow who a hop into this ring may reach (empty = every target tenant / no group rule).</li></ul></li><li><p><strong>Edit</strong> reopens the dialog for organization rings; system shadows carry the badge of what they customize.</p></li></ol><p>Each card also states its required-gate count — the gates a release on that ring must satisfy (see <a href="/shipperdog/snapshot/how-to/console/quality-gates">quality gates</a>).</p><h2 id="answer-why-can-t-i-promote-first" tabindex="-1">Answer &quot;why can&#39;t I promote?&quot; first <a class="header-anchor" href="#answer-why-can-t-i-promote-first" aria-label="Permalink to &quot;Answer &quot;why can&#39;t I promote?&quot; first&quot;">​</a></h2><p>On the release dashboard&#39;s <strong>Distribution</strong> block, click <strong>Why can&#39;t I promote?</strong> — the precheck runs the exact evaluation the promote act runs, as a read:</p><ul><li>the verdict,</li><li>the complete blocker list — every gate, approval, eligibility, and policy refusal named with its evidence,</li><li>the target ring&#39;s gate states and the approval leg&#39;s standing.</li></ul><p>Nothing is written and no approval round is opened; the first promote attempt opens the round a policy demands.</p><h2 id="promote-one-hop-at-a-time" tabindex="-1">Promote, one hop at a time <a class="header-anchor" href="#promote-one-hop-at-a-time" aria-label="Permalink to &quot;Promote, one hop at a time&quot;">​</a></h2><ol><li>On an ACTIVE release, click <strong>Promote to next ring</strong>.</li><li>The engine walks the release to the next ring in your organization&#39;s effective order — re-checking everything the precheck showed. The final ring carries the release to <strong>PROMOTED</strong>.</li><li>Any refusal stops the walk: the blocker list prints in the warning box and is recorded permanently on the promotion timeline. Fix the blocker, precheck again, promote again.</li></ol><p>Every hop and every refusal lands on the <strong>Promotion timeline</strong> with its actor, tenants moved, and evidence — the append-only record the dashboard renders beside the state timeline.</p><h2 id="promote-selectively-the-staged-pattern" tabindex="-1">Promote selectively (the staged pattern) <a class="header-anchor" href="#promote-selectively-the-staged-pattern" aria-label="Permalink to &quot;Promote selectively (the staged pattern)&quot;">​</a></h2><p>To widen only some target tenants first — Acme this morning, Contoso after lunch — use the CLI&#39;s selective form:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shipperdog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> promote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> R-1028</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tenant</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ACME_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Absent <code>--tenant</code>, the hop moves every target. For production rollouts in percentage stages, see <a href="/shipperdog/snapshot/how-to/console/staged-rollout">staged tenant rollout</a>.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/staged-rollout">staged rollout</a> · <a href="/shipperdog/snapshot/how-to/console/rollback">roll back a release</a> · <a href="/shipperdog/snapshot/concepts/rings-and-rollout">rings and rollout concepts</a></p>',19)])])}const y=o(n,[["render",i]]);export{u as __pageData,y as default};
